const b=$json.body??$json;
const required=['organization_id','agent_id','idempotency_key','input'];
const missing=required.filter(k=>b[k]===undefined||b[k]===null||b[k]==='');
if(missing.length) throw new Error('Missing required tenant fields: '+missing.join(', '));
const allowed=['campaign.sequence_due','campaign.manual_send','campaign.retry','campaign.reply_received','campaign.unsubscribe'];
const eventType=String(b.event_type||'campaign.sequence_due');
if(!allowed.includes(eventType)) throw new Error('Unsupported outbound email event');
const input=b.input||{};
const email=String(input.email||input.recipient_email||'').trim().toLowerCase();
const customerKey=String(b.customer_id||input.customer_key||email||'').trim();
if(!customerKey) throw new Error('customer_id, customer_key, or recipient email required');
if(eventType!=='campaign.reply_received'&&eventType!=='campaign.unsubscribe'&&!email) throw new Error('Recipient email is required');
return [{json:{
  organization_id:String(b.organization_id),
  agent_id:String(b.agent_id),
  conversation_id:b.conversation_id||null,
  customer_id:b.customer_id||null,
  lead_id:b.lead_id||input.lead_id||null,
  campaign_id:b.campaign_id||input.campaign_id||null,
  sequence_step:Number(b.sequence_step??input.sequence_step??1),
  customer_key:customerKey,
  idempotency_key:String(b.idempotency_key),
  channel:'email',
  event_type:eventType,
  input:{...input,email},
  workflow_key:'outbound_email_crm_v5',
  received_at:new Date().toISOString()
}}];

const env=$('Validate Outbound Envelope').first().json;
const rows=Array.isArray($json)?$json:[$json];
const snap=rows[0];
if(!snap) throw new Error('Runtime snapshot not found');
const schema={
 action:'send|skip|reschedule|handoff|stop',
 subject:'string|null',
 message:'string|null',
 reason:'string',
 lead_stage:'new|contacted|qualified|nurturing|appointment|won|lost|disqualified',
 next_step:'integer|null',
 next_send_at:'ISO-8601|null',
 reply_classification:'interested|not_interested|question|objection|unsubscribe|out_of_office|bounce|other|null',
 priority:'low|normal|high|urgent',
 handoff_required:'boolean',
 handoff_reason:'string|null',
 stop_sequence:'boolean',
 memory_facts:[{type:'campaign|preference|objection|fact',summary:'string',confidence:'0-1'}]
};
return [{json:{
 ...env,
 execution_id:$('Queue Email Execution').first().json.execution_id,
 snapshot:snap,
 provider_request:{
   execution_id:$('Queue Email Execution').first().json.execution_id,
   organization_id:env.organization_id,
   agent_id:env.agent_id,
   instructions:snap.compiled_prompt+'\nUse only supplied tenant knowledge, CRM state, campaign rules and contact context. Never invent facts. Respect suppression and opt-out policy. Return strict JSON only using this schema: '+JSON.stringify(schema),
   input:JSON.stringify({
     event_type:env.event_type,
     recipient:env.input,
     campaign_id:env.campaign_id,
     sequence_step:env.sequence_step,
     customer_id:env.customer_id,
     lead_id:env.lead_id
   })
 }
}}];

const ctx=$('Build Email Decision Request').first().json;
let raw=$json.output_text||$json.text||$json.response_text;
if(!raw&&Array.isArray($json.output)) raw=$json.output.flatMap(x=>x.content||[]).map(x=>x.text||x.output_text||'').join('');
raw=String(raw||'').replace(/^```json\s*/i,'').replace(/```$/,'').trim();
let d; try{d=JSON.parse(raw)}catch(e){throw new Error('Invalid outbound email AI JSON: '+raw.slice(0,300))}
const actions=['send','skip','reschedule','handoff','stop'];
const stages=['new','contacted','qualified','nurturing','appointment','won','lost','disqualified'];
const priorities=['low','normal','high','urgent'];
const replies=['interested','not_interested','question','objection','unsubscribe','out_of_office','bounce','other'];
d.action=actions.includes(d.action)?d.action:'skip';
d.lead_stage=stages.includes(d.lead_stage)?d.lead_stage:'nurturing';
d.priority=priorities.includes(d.priority)?d.priority:'normal';
d.reply_classification=replies.includes(d.reply_classification)?d.reply_classification:null;
d.handoff_required=Boolean(d.handoff_required||d.action==='handoff');
d.stop_sequence=Boolean(d.stop_sequence||d.action==='stop'||d.reply_classification==='unsubscribe'||d.reply_classification==='not_interested'||d.reply_classification==='bounce');
d.next_step=d.next_step===null||d.next_step===undefined?null:Math.max(1,Math.round(Number(d.next_step)||1));
d.memory_facts=Array.isArray(d.memory_facts)?d.memory_facts:[];
return [{json:{...ctx,decision:d,provider_usage:$json.usage||{},provider_response_id:$json.id||null}}];

const r=$json;
const actions=[];
if(r.handoff) actions.push({type:'handoff',payload:r.handoff});
if(r.follow_up) actions.push({type:'follow_up',payload:r.follow_up});
if(r.email_action) actions.push({type:'reply',payload:r.email_action});
return [{json:{...r,actions}}];
